-- Schema for the synthetic repair-shop dataset (generated by generate_data.py).
--
-- Written for DuckDB with standard SQL types and constraints, so it reads the
-- same way in PostgreSQL. Each table is created after the tables its foreign
-- keys point to. All timestamps are local Vancouver time.
--
-- The constraints enforce what a single row can prove: types, keys and allowed
-- values. Rules that need other rows or tables (every completed job has a
-- payment, no duplicate customers) are checked by sql/10_data_quality_checks.sql.

CREATE TABLE cities (
    city_id      INTEGER PRIMARY KEY,
    city_name    VARCHAR NOT NULL UNIQUE,
    travel_fee   DECIMAL(6, 2) NOT NULL CHECK (travel_fee >= 0),
    service_days VARCHAR NOT NULL              -- 'Every day', or the route days for outer areas
);

CREATE TABLE price_tiers (
    tier_id          INTEGER PRIMARY KEY,
    tier_name        VARCHAR NOT NULL UNIQUE,  -- Value, Recommended, Premium
    price_multiplier DECIMAL(4, 2) NOT NULL CHECK (price_multiplier > 0),
    warranty_months  INTEGER NOT NULL CHECK (warranty_months > 0)
);

CREATE TABLE services (
    service_id       INTEGER PRIMARY KEY,
    service_name     VARCHAR NOT NULL,
    device_type      VARCHAR NOT NULL CHECK (device_type IN ('phone', 'laptop')),
    base_price       DECIMAL(8, 2) NOT NULL CHECK (base_price > 0),  -- before model and tier adjustments
    duration_minutes INTEGER NOT NULL CHECK (duration_minutes > 0),  -- typical hands-on time
    UNIQUE (service_name, device_type)
);

CREATE TABLE device_models (
    model_id     INTEGER PRIMARY KEY,
    brand        VARCHAR NOT NULL,
    model_name   VARCHAR NOT NULL UNIQUE,
    device_type  VARCHAR NOT NULL CHECK (device_type IN ('phone', 'laptop')),
    release_year INTEGER NOT NULL
);

CREATE TABLE technicians (
    technician_id   INTEGER PRIMARY KEY,
    technician_name VARCHAR NOT NULL,
    hired_on        DATE NOT NULL,
    left_on         DATE,                      -- NULL while still on the team
    employment_type VARCHAR NOT NULL CHECK (employment_type IN ('full-time', 'part-time')),
    CHECK (left_on IS NULL OR left_on >= hired_on)
);

-- One row per day a technician actually worked (a timesheet, up to the snapshot).
CREATE TABLE technician_shifts (
    technician_id INTEGER NOT NULL REFERENCES technicians (technician_id),
    shift_date    DATE NOT NULL,
    shift_hours   INTEGER NOT NULL CHECK (shift_hours > 0),
    PRIMARY KEY (technician_id, shift_date)
);

CREATE TABLE customers (
    customer_id INTEGER PRIMARY KEY,
    full_name   VARCHAR NOT NULL,
    email       VARCHAR NOT NULL,              -- not UNIQUE on purpose: duplicate sign-ups happen
    created_at  TIMESTAMP NOT NULL
);

CREATE TABLE bookings (
    booking_id    INTEGER PRIMARY KEY,
    customer_id   INTEGER NOT NULL REFERENCES customers (customer_id),
    city_id       INTEGER NOT NULL REFERENCES cities (city_id),
    model_id      INTEGER NOT NULL REFERENCES device_models (model_id),
    service_id    INTEGER NOT NULL REFERENCES services (service_id),
    tier_id       INTEGER NOT NULL REFERENCES price_tiers (tier_id),
    technician_id INTEGER REFERENCES technicians (technician_id),   -- assigned at confirmation
    status        VARCHAR NOT NULL
                  CHECK (status IN ('requested', 'confirmed', 'completed', 'cancelled')),
    created_at    TIMESTAMP NOT NULL,          -- when the customer asked for the repair
    confirmed_at  TIMESTAMP,
    scheduled_for TIMESTAMP NOT NULL,          -- appointment start (the requested time if never confirmed)
    completed_at  TIMESTAMP,
    cancelled_at  TIMESTAMP,
    quoted_price  DECIMAL(8, 2) NOT NULL CHECK (quoted_price > 0),  -- includes the travel fee
    final_price   DECIMAL(8, 2) CHECK (final_price > 0)             -- what was charged; NULL unless completed
);

CREATE TABLE payments (
    payment_id INTEGER PRIMARY KEY,
    booking_id INTEGER NOT NULL REFERENCES bookings (booking_id),
    paid_at    TIMESTAMP NOT NULL,
    amount     DECIMAL(8, 2) NOT NULL CHECK (amount > 0),
    method     VARCHAR NOT NULL CHECK (method IN ('card', 'e-transfer', 'cash'))
);

CREATE TABLE reviews (
    review_id   INTEGER PRIMARY KEY,
    booking_id  INTEGER NOT NULL UNIQUE REFERENCES bookings (booking_id),  -- at most one per job
    rating      SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5),
    reviewed_at TIMESTAMP NOT NULL
);

CREATE TABLE warranty_claims (
    claim_id   INTEGER PRIMARY KEY,
    booking_id INTEGER NOT NULL REFERENCES bookings (booking_id),
    claimed_at TIMESTAMP NOT NULL,
    reason     VARCHAR NOT NULL,
    outcome    VARCHAR NOT NULL CHECK (outcome IN ('approved', 'rejected'))
);
